from pydantic import BaseModel, Field, field_validator
from shared.url_guard import UnsafeURLError, check_url_syntax
from datetime import datetime
from typing import Optional

#when we create a pipeline, we just define its name, description. id, created_at are autogenerated by the DB. is_active field also always starts as TRUE
def validate_callback_url_helper(v: Optional[str])->Optional[str]:
    """A webhook must be an http or https URL. Whether it points somewhere the worker may call is checked again when it
    is called (shared/url_guard.py), because a name can lead somewhere else later."""
    if v is None:
        return v
    try:
        return check_url_syntax(v)
    except UnsafeURLError as error:
        raise ValueError(str(error)) from None

# tenant_id will be in the route itself. Each pipeline is scoped to some specific tenant. 
class PipelineCreate(BaseModel):
    name: str=Field(min_length=1, max_length=255)
    description: Optional[str]=None
    callback_url: Optional[str]=None

    _check_callback_url=field_validator("callback_url")(validate_callback_url_helper)

# Each pipeline belongs to a specific tenant and that CANNOT be updated
class PipelineUpdate(BaseModel): #we can update the name, description and is_active status
    name: Optional[str]=Field(None, min_length=1, max_length=255)
    description: Optional[str]=None
    is_active: Optional[bool]=None
    callback_url: Optional[str]=None

    _check_callback_url=field_validator("callback_url")(validate_callback_url_helper)

class PipelineResponse(BaseModel):
    id: int
    tenant_id: int
    name: str
    description: Optional[str]
    created_at: datetime
    is_active: bool
    callback_url: Optional[str]

    model_config={
        "from_attributes":True
    }